from collections import defaultdict

class Solution:
    def longestSelfContainedSubstring(self, s: str) -> int:
        n = len(s)
        pos = defaultdict(list)
        for i, ch in enumerate(s):
            pos[ch].append(i)
        ans = -1
        for sep, ps in pos.items():
            bounds = [-1] + ps + [n]
            for b in range(len(bounds) - 1):
                l, r = bounds[b] + 1, bounds[b + 1] - 1
                if l > r:
                    continue
                ok = True
                for i in range(l, r + 1):
                    pl = pos[s[i]]
                    if pl[0] < l or pl[-1] > r:
                        ok = False
                        break
                if ok:
                    ans = max(ans, r - l + 1)
        return ans

