class Solution {
public:
    int longestSelfContainedSubstring(string s) {
        int n = s.size();
        vector<vector<int>> pos(26);
        for (int i = 0; i < n; i++) pos[s[i] - 'a'].push_back(i);
        int ans = -1;
        for (int sep = 0; sep < 26; sep++) {
            if (pos[sep].empty()) continue;
            vector<int>& ps = pos[sep];
            vector<int> bounds;
            bounds.push_back(-1);
            for (int p : ps) bounds.push_back(p);
            bounds.push_back(n);
            for (int b = 0; b + 1 < (int)bounds.size(); b++) {
                int l = bounds[b] + 1, r = bounds[b + 1] - 1;
                if (l > r) continue;
                bool ok = true;
                for (int i = l; i <= r && ok; i++) {
                    auto& pl = pos[s[i] - 'a'];
                    if (pl.front() < l || pl.back() > r) ok = false;
                }
                if (ok) ans = max(ans, r - l + 1);
            }
        }
        return ans;
    }
};

