class Solution {
    public int longestSelfContainedSubstring(String s) {
        int n = s.length();
        List<List<Integer>> pos = new ArrayList<>();
        for (int i = 0; i < 26; i++) pos.add(new ArrayList<>());
        for (int i = 0; i < n; i++) pos.get(s.charAt(i) - 'a').add(i);
        int ans = -1;
        for (int sep = 0; sep < 26; sep++) {
            if (pos.get(sep).isEmpty()) continue;
            List<Integer> ps = pos.get(sep);
            List<Integer> bounds = new ArrayList<>();
            bounds.add(-1);
            bounds.addAll(ps);
            bounds.add(n);
            for (int b = 0; b + 1 < bounds.size(); b++) {
                int l = bounds.get(b) + 1, r = bounds.get(b + 1) - 1;
                if (l > r) continue;
                boolean ok = true;
                for (int i = l; i <= r && ok; i++) {
                    List<Integer> pl = pos.get(s.charAt(i) - 'a');
                    if (pl.get(0) < l || pl.get(pl.size() - 1) > r) ok = false;
                }
                if (ok) ans = Math.max(ans, r - l + 1);
            }
        }
        return ans;
    }
}

