class Solution:
    def longestSelfContainedSubstring(self, s: str) -> int:
        n = len(s)
        total = [0] * 26
        for ch in s:
            total[ord(ch) - 97] += 1
        ans = -1
        for l in range(n):
            cnt = [0] * 26
            leak = 0
            for r in range(l, n):
                c = ord(s[r]) - 97
                cnt[c] += 1
                if cnt[c] == 1:
                    leak += 1
                elif cnt[c] == total[c]:
                    leak -= 1
                if leak == 0 and r > l:
                    ans = max(ans, r - l + 1)
        return ans

